css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .rig { position: absolute; left: 14%; right: 14%; top: 6%; bottom: 6%; transform-origin: 50% 8%; animation: chute-sway calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
.loader .canopy { position: absolute; left: 0; top: 0; width: 100%; height: 38%; border-radius: 50% 50% 12% 12% / 96% 96% 30% 30%; background: repeating-linear-gradient(90deg, var(--accent) 0 12%, var(--accent-2) 0 24%); animation: chute-billow calc(var(--loader-speed) * 1.7) ease-in-out infinite; }
.loader .cord { position: absolute; top: 36%; width: 2%; height: 32%; background: color-mix(in srgb, #0f172a 45%, transparent); }
.loader .cord:nth-of-type(2) { left: 22%; transform: rotate(9deg); }
.loader .cord:nth-of-type(3) { right: 22%; transform: rotate(-9deg); }
.loader .pod { position: absolute; left: 34%; bottom: 6%; width: 32%; height: 26%; border-radius: 40% 40% 22% 22% / 60% 60% 26% 26%; background: linear-gradient(color-mix(in srgb, #fff 25%, var(--accent)), var(--accent)); }
@keyframes chute-sway { 0%, 100% { transform: rotate(-7deg) translateY(-3%); } 50% { transform: rotate(7deg) translateY(3%); } }
@keyframes chute-billow { 0%, 100% { transform: scaleX(1) scaleY(1); } 50% { transform: scaleX(1.06) scaleY(.92); } }
